void UploadTexImage(
    TexImageFunctionID function_id,
    GLenum target,
    GLint level,
    GLint internalformat,
    GLint border,
    GLenum format,
    GLenum type,
    GLsizei depth,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    ImageData* pixels,
    const IntRect& source_image_rect,
    GLint unpack_image_height)
{
    // Validate border
    if (border != 0) {
        return;
    }

    // Adjust source rectangle based on pixel data and unpack settings
    GLint source_width = source_image_rect.z - source_image_rect.x;
    GLint source_height = source_image_rect.w - source_image_rect.y;

    // Validate the input pixel data and source rectangle
    if (!pixels || source_width <= 0 || source_height <= 0) {
        return;
    }

    // Set unpack parameters if needed
    if (unpack_image_height > 0) {
        // Implementation of unpack settings
    }

    // Choose the appropriate function based on function_id
    switch (function_id) {
        case TEXTURE_2D:
            glTexImage2D(
                target, level, internalformat,
                source_width, source_height, border,
                format, type, pixels->data);
            break;
        case TEXTURE_3D:
            glTexImage3D(
                target, level, internalformat,
                source_width, source_height, depth, border,
                format, type, pixels->data);
            break;
        default:
            break;
    }
}

void uploadTexImageToWebGLTexture(
    TexImageFunctionID function_id,
    GLenum target,
    GLint level,
    GLint internalformat,
    GLint border,
    GLenum format,
    GLenum type,
    GLsizei depth,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    ImageData* pixels,
    const IntRect* source_image_rect,
    GLint unpack_image_height) {

    // Validate that the WebGL context is valid and active
    if (!isWebGLRenderingContextActive()) {
        return;
    }

    // Validate border parameter - must be 0 according to WebGL spec
    if (border != 0) {
        return;
    }

    // Adjust source image rectangle if needed
    GLint adjusted_width = source_image_rect->x + source_image_rect->width;
    GLint adjusted_height = source_image_rect->y + source_image_rect->height;

    // Adjust image data pointer to the source rectangle offset
    void* adjusted_pixels = (void*)((char*)pixels + source_image_rect->x * getPixelSize(format, type) + source_image_rect->y * source_image_rect->width * getPixelSize(format, type));

    switch (function_id) {
        case TEXTURE_2D:
            glTexImage2D(
                target,             // target
                level,              // level
                internalformat,     // internalFormat
                source_image_rect->width, // width
                source_image_rect->height, // height
                border,             // border
                format,             // format
                type,               // type
                adjusted_pixels     // pixels
            );
            break;

        case TEXTURE_3D:
            glTexImage3D(
                target,             // target
                level,              // level
                internalformat,     // internalFormat
                source_image_rect->width, // width
                source_image_rect->height, // height
                depth,              // depth
                border,             // border
                format,             // format
                type,               // type
                adjusted_pixels     // pixels
            );
            break;

        default:
            break;
    }

    glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, unpack_image_height);
}

void upload_texture_image(TexImageFunctionID function_id, GLenum target, GLint level,
                          GLint internalformat, GLint border, GLenum format, GLenum type,
                          GLsizei depth, GLint xoffset, GLint yoffset, GLint zoffset,
                          ImageData* pixels, const IntRect* source_image_rect,
                          GLint unpack_image_height) {
    if (!pixels || border != 0) {
        return;
    }

    GLint width = source_image_rect->x2 - source_image_rect->x1;
    GLint height = source_image_rect->y2 - source_image_rect->y1;

    if (width <= 0 || height <= 0) {
        return;
    }

    GLint pixel_data_type_size = 0;
    switch (type) {
        case GL_UNSIGNED_BYTE: pixel_data_type_size = 1; break;
        case GL_UNSIGNED_SHORT: pixel_data_type_size = 2; break;
        case GL_UNSIGNED_INT: pixel_data_type_size = 4; break;
        default: return;
    }

    GLint bytes_per_pixel = (internalformat == GL_RGBA) ? 4 :
                            (internalformat == GL_RGB) ? 3 :
                            (internalformat == GL_LUMINANCE) ? 1 : 0;

    if (bytes_per_pixel == 0) {
        return;
    }

    GLint pixel_stride = width * bytes_per_pixel * pixel_data_type_size;
    void* pixel_data = (void*)(((char*)pixels) + source_image_rect->x1 * bytes_per_pixel * pixel_data_type_size);

    if (function_id == TEXT_IMAGE_3D) {
        glTexImage3D(target, level, internalformat, width, height, depth,
                     border, format, type, pixel_data);
    } else if (function_id == TEXT_SUB_IMAGE_3D) {
        glTexSubImage3D(target, level, xoffset, yoffset, zoffset, width, height, depth,
                        format, type, pixel_data);
    } else if (function_id == TEXT_IMAGE_2D) {
        glTexImage2D(target, level, internalformat, width, height, border,
                     format, type, pixel_data);
    } else if (function_id == TEXT_SUB_IMAGE_2D) {
        glTexSubImage2D(target, level, xoffset, yoffset, width, height, format, type, pixel_data);
    } else {
        return;
    }
}

void uploadTexImageToWebGL(
    TexImageFunctionID function_id,
    GLenum target,
    GLint level,
    GLint internalformat,
    GLint border,
    GLenum format,
    GLenum type,
    GLsizei depth,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    ImageData* pixels,
    const IntRect& source_image_rect,
    GLint unpack_image_height) {

    // Validate border
    if (border != 0) {
        // Invalid value for border
        return;
    }

    // Adjust source rectangle as needed
    GLint width = source_image_rect.right - source_image_rect.left;
    GLint height = source_image_rect.bottom - source_image_rect.top;

    // Set up pixel store parameters for unpacking
    if (unpack_image_height > 0) {
        glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, unpack_image_height);
    }

    // Call the appropriate WebGL function depending on function_id
    switch(function_id) {
        case TEXTURE_2D:
            glTexImage2D(
                target, level, internalformat, width, height, border,
                format, type, pixels);
            break;
        case TEXTURE_3D:
            glTexImage3D(
                target, level, internalformat, width, height, depth,
                border, format, type, pixels);
            break;
        default:
            // Invalid function ID
            return;
    }

    // Reset the unpack image height to default if it was changed
    if (unpack_image_height > 0) {
        glPixelStorei(GL_UNPACK_IMAGE_HEIGHT, 0);
    }
}

void uploadTexImageToWebGL(TexImageFunctionID function_id, GLenum target, GLint level, GLint internalformat,
                           GLint border, GLenum format, GLenum type, GLsizei depth, GLint xoffset,
                           GLint yoffset, GLint zoffset, ImageData* pixels, const IntRect* source_image_rect,
                           GLint unpack_image_height) {
    // Context and parameter validation logic would go here
    if (!pixels) {
        return; // Or handle error as needed
    }

    // Adjust source image rectangle if required based on the logic
    GLint width = source_image_rect->x2 - source_image_rect->x1;
    GLint height = source_image_rect->y2 - source_image_rect->y1;

    // Depending on function_id and target, determine which WebGL function to call
    if (function_id == TEXTURE_2D) {
        glTexImage2D(target, level, internalformat, width, height, border, format, type, pixels->data);
    } else if (function_id == TEXTURE_3D) {
        glTexImage3D(target, level, internalformat, width, height, depth, border, format, type, pixels->data);
